import api.SettlementApi;
import domain.DailyLine;
import domain.FxQuote;
import service.ReconcileService.Mismatch;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;

/** End-to-end checks through the public facade, against the sample data in fixtures/. */
public class SettlementE2ETest {
    private static final LocalDate FROM = LocalDate.of(2026, 10, 1);
    private static final LocalDate TO = LocalDate.of(2026, 10, 5);

    public static void main(String[] args) {
        TestSupport t = new TestSupport("e2e");
        SettlementApi api = SettlementApi.fromDefaultConfig();

        t.test("settlement for 10/01-10/05 matches every partner statement", () -> {
            List<Mismatch> m = api.reconcile(FROM, TO);
            TestSupport.check(m.isEmpty(), "settlement differs from partner statements:\n"
                    + api.reconcileReport(FROM, TO));
        });

        t.test("partner P-1001 is paid the statement amount for 10/03", () -> {
            DailyLine l = line(api.daily(FROM, TO), LocalDate.of(2026, 10, 3), "P-1001");
            TestSupport.eq(3, l.count(), "transaction count");
            TestSupport.eq(524_145L, l.grossKrw(), "gross KRW");
            TestSupport.eq(517_856L, l.netKrw(), "net KRW after fee");
        });

        t.test("weekday settlement is unchanged", () -> {
            DailyLine l = line(api.daily(FROM, TO), LocalDate.of(2026, 10, 2), "P-1002");
            TestSupport.eq(397_234L, l.grossKrw(), "gross KRW 10/02 P-1002");
        });

        t.test("inactive partners are not settled", () -> {
            TestSupport.check(api.daily(FROM, TO).stream().noneMatch(l -> l.partnerId().equals("P-1004")),
                    "P-1004 should be excluded");
        });

        t.test("accounting export has one row per partner per day", () -> {
            String csv = api.exportCsv(FROM, TO);
            TestSupport.eq(16L, csv.lines().count(), "csv lines incl. header");
        });

        t.test("app rate board shows the published quotes", () -> {
            List<FxQuote> b = api.rateBoard(LocalDate.of(2026, 10, 3));
            TestSupport.eq(4, b.size(), "board size");
            TestSupport.eq(new BigDecimal("1386.02"), b.get(0).rate(), "USD on board");
            TestSupport.eq(new BigDecimal("923.98"), b.get(2).rate(), "JPY on board");
            TestSupport.check(api.rateBoardText(LocalDate.of(2026, 10, 3)).contains("1,386.02원"), "board text");
        });

        t.finish();
    }

    private static DailyLine line(List<DailyLine> lines, LocalDate d, String partner) {
        return lines.stream().filter(l -> l.date().equals(d) && l.partnerId().equals(partner)).findFirst()
                .orElseThrow(() -> new AssertionError("no settlement line for " + d + " " + partner));
    }
}
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

/** Tiny assertion runner (no external test framework available on the batch host). */
final class TestSupport {
    private final String suite;
    private final List<String> failures = new ArrayList<>();
    private int passed;

    TestSupport(String suite) {
        this.suite = suite;
    }

    interface Body { void run() throws Exception; }

    void test(String name, Body body) {
        try {
            body.run();
            passed++;
            System.out.println("ok   - " + name);
        } catch (AssertionError | Exception e) {
            failures.add(name + ": " + e.getMessage());
            System.out.println("FAIL - " + name + ": " + e.getMessage());
        }
    }

    static void eq(Object expected, Object actual, String msg) {
        if (!Objects.equals(expected, actual)) {
            throw new AssertionError(msg + " (expected " + expected + ", got " + actual + ")");
        }
    }

    static void check(boolean cond, String msg) {
        if (!cond) throw new AssertionError(msg);
    }

    void finish() {
        System.out.printf("%s: %d passed, %d failed%n", suite, passed, failures.size());
        if (!failures.isEmpty()) System.exit(1);
    }
}
import config.AppConfig;
import domain.DailyLine;
import domain.FxQuote;
import service.ReconcileService.Mismatch;
import domain.StatementRow;
import infra.FxqClient;
import service.BusinessDateResolver;
import service.CurrencyPairs;
import service.ReconcileService;
import util.Csv;
import util.Money;

import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.List;

public class UnitChecks {
    public static void main(String[] args) {
        TestSupport t = new TestSupport("unit");

        t.test("krw conversion rounds half-up to whole won", () -> {
            TestSupport.eq(16663L, Money.toKrw(new BigDecimal("12.05"), new BigDecimal("1382.80"), 1), "12.05 USD");
            TestSupport.eq(-16663L, Money.toKrw(new BigDecimal("-12.05"), new BigDecimal("1382.80"), 1), "refund");
        });

        t.test("yen is quoted per 100", () -> {
            TestSupport.eq(100, CurrencyPairs.unitOf("JPY"), "unit");
            TestSupport.eq(9250L, Money.toKrw(new BigDecimal("1000"), new BigDecimal("925.00"), 100), "1000 JPY");
        });

        t.test("fee truncates fractional won", () -> {
            TestSupport.eq(1234L, Money.fee(102_850, 120), "1.2% of 102,850");
            TestSupport.eq(0L, Money.fee(-5000, 120), "no fee on net refunds");
        });

        t.test("won formatting", () -> TestSupport.eq("1,234,567", Money.won(1_234_567), "format"));

        t.test("csv split handles quotes", () -> {
            TestSupport.eq(List.of("a", "b,c", "d\"e"), Csv.split("a,\"b,c\",\"d\"\"e\""), "split");
        });

        t.test("approval just after KST midnight belongs to next date", () -> {
            BusinessDateResolver r = new BusinessDateResolver(ZoneId.of("Asia/Seoul"));
            TestSupport.eq(LocalDate.of(2026, 10, 3), r.dateOf(Instant.parse("2026-10-02T15:20:00Z")), "KST date");
            TestSupport.eq(LocalDate.of(2026, 10, 2), r.dateOf(Instant.parse("2026-10-02T14:59:59Z")), "KST date");
        });

        t.test("quote line parsing", () -> {
            FxQuote q = FxqClient.parse("EURKRW 2026-10-01 1598.40");
            TestSupport.eq("EURKRW", q.pair(), "pair");
            TestSupport.eq(LocalDate.of(2026, 10, 1), q.date(), "date");
            TestSupport.eq(new BigDecimal("1598.40"), q.rate(), "rate");
        });

        t.test("reconcile flags gross differences and missing rows", () -> {
            LocalDate d = LocalDate.of(2026, 9, 30);
            List<Mismatch> m = new ReconcileService().compare(
                    List.of(new DailyLine(d, "P-1", 2, 1000, 12)),
                    List.of(new StatementRow(d, "P-1", 2, 1001), new StatementRow(d, "P-2", 1, 50)));
            TestSupport.eq(2, m.size(), "mismatch count");
            TestSupport.eq("gross", m.get(0).field(), "first");
            TestSupport.eq("missing", m.get(1).field(), "second");
        });

        t.test("config reads board currencies", () -> {
            TestSupport.eq(List.of("USD", "EUR", "JPY", "CNY"), AppConfig.load().boardCurrencies(), "currencies");
        });

        t.finish();
    }
}

