            vendorCalls++;
            return FxqClient.parse(client.rate(pair, date));
        });
    }

    /**
     * Rate applied to card transactions of the given KST settlement date.
     * On vendor holidays the default source carries the previous business day's value, so the settlement source is queried instead.
